# -*- coding: utf-8 -*-
# one-time patch v41: 8 more abbreviations in the abbreviations tab, sw.js cache bump
import hashlib, json
b = open("index.html", "rb").read()
assert hashlib.sha256(b).hexdigest() == "364e9ed7ed529ab8797073862926d4a4a5fa180969274ed3e44efc77588763a6", "index.html is not the expected version"
h = b.decode("utf-8")
pairs = json.loads("[[\",{\\\"a\\\":\\\"תפא״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"תער״ב\\\",\\\"e\\\":\\\"(המשך) תער״ב\\\",\\\"m\\\":\\\"סדרת מאמרים של אדמו״ר הרש״ב שהחל לומר בחג השבועות בשנת תרע״ב, בד״ה ״בשעה שהקדימו ישראל נעשה לנשמע״.\\\",\\\"s\\\":\\\"מופיע 736 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"תפא״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"ע״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"עטר״ת\\\",\\\"e\\\":\\\"ספר המאמרים עטר״ת\\\",\\\"m\\\":\\\"חלק מ״ספר המאמרים (אדמו״ר הרש״ב)״ הכולל את המאמרים שאמר בשנת תרע״ט.\\\",\\\"s\\\":\\\"מופיע 361 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"ע״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"והאגה״ק\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"ו״ה\\\",\\\"e\\\":\\\"האותיות ו-ה בשם הוי׳\\\",\\\"m\\\":\\\"י-ה הוא החלק הראשון של השם, ו-ה החלק השני.\\\",\\\"s\\\":\\\"מופיע 352 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"והאגה״ק\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"ש״ח\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"שז״ע\\\",\\\"e\\\":\\\"שזהו עניין\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"מופיע 147 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"ש״ח\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"חז״ל\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"ח״ז\\\",\\\"e\\\":\\\"חלק ז׳\\\",\\\"m\\\":\\\"כמו בהפניה ״אגרות קודש ח״ז״.\\\",\\\"s\\\":\\\"מופיע 125 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"חז״ל\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"וז״ש\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"וז״ע\\\",\\\"e\\\":\\\"וזה עניין\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"מופיע 121 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"וז״ש\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"תר״י\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"תרח״ץ\\\",\\\"e\\\":\\\"שנת תרצ״ח\\\",\\\"m\\\":\\\"כותבים תרח״ץ ולא תרצ״ח, כי צירוף האותיות ״תרצח״ שלילי.\\\",\\\"s\\\":\\\"מופיע 108 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"תר״י\\\",\\\"e\\\":\"], [\",{\\\"a\\\":\\\"הול״ל\\\",\\\"e\\\":\", \",{\\\"a\\\":\\\"הו״ל\\\",\\\"e\\\":\\\"הוה לי׳\\\",\\\"m\\\":\\\"\\\",\\\"s\\\":\\\"מופיע 98 פעמים בספרים שנסרקו\\\"},{\\\"a\\\":\\\"הול״ל\\\",\\\"e\\\":\"]]")
pairs.append(["עם הפיענוח שלהם (1,952).", "עם הפיענוח שלהם (1,960)."])
for a, r in pairs:
    assert h.count(a) == 1, a
    h = h.replace(a, r)
out = h.encode("utf-8")
assert hashlib.sha256(out).hexdigest() == "3f1191c56a205ba74b9904237604340bf24e5f630aec6b5689fb87b6a51e76ca", "patched index.html hash mismatch"
open("index.html", "wb").write(out)
sw = open("sw.js", encoding="utf-8").read()
old = 'const VERSION = "bar-hasaga-v40-abbr-nolabel";'
assert sw.count(old) == 1
open("sw.js", "w", encoding="utf-8").write(sw.replace(old, 'const VERSION = "bar-hasaga-v41-abbr-more";'))
print("ok")
